#!/usr/bin/env python3
"""MESA: dependency-free production build for a static culinary editorial site."""
from __future__ import annotations
import json, html, os, shutil, re
from pathlib import Path
from urllib.parse import quote
ROOT=Path(__file__).resolve().parent
DIST=ROOT/'docs'
BASE=os.environ.get('MESA_BASE','/MESA').rstrip('/')
ORIGIN=os.environ.get('MESA_SITE','https://pfxamd.github.io').rstrip('/')
RECIPES=json.loads((ROOT/'content/recipes.json').read_text())
STORIES=json.loads((ROOT/'content/stories.json').read_text())
IMAGES={v['id']:v for v in json.loads((ROOT/'data/images.json').read_text())['images']}
CATEGORIES=('Small Plates','The Main Table','Something Sweet')
def e(s):return html.escape(str(s),quote=True)
def path(url='/'):
 if not url.startswith('/'):url='/'+url
 return BASE+url
def image(n,alt='',cls='',eager=False,priority=False):
 item=IMAGES[n]
 return f'<img class="{e(cls)}" src="{path(item["src"])}" width="{item["width"]}" height="{item["height"]}" alt="{e(alt)}" decoding="async" loading="{"eager" if eager else "lazy"}"'+(' fetchpriority="high"' if priority else '')+'>'
def media_src(src):return path(src)
def nav(current):
 navlinks=[('recipes','Recipes','/recipes/'),('kitchen','The Kitchen','/kitchen/'),('stories','Stories','/stories/'),('about','About','/about/')]
 links=''.join(f'<a href="{path(href)}"'+(' aria-current="page"' if key==current else '')+f'>{label}</a>' for key,label,href in navlinks)
 return f'''<div class="announcement"><span>THE EVERYDAY TABLE <b>✳</b> VOLUME 01</span><span>FROM MARKET TO TABLE <span aria-hidden="true">↗</span></span></div>
<header class="site-header" id="top"><a class="logo" href="{path()}" aria-label="MESA, home">MESA<span aria-hidden="true">●</span></a>
<nav class="desktop-nav" aria-label="Primary navigation">{links}</nav>
<div class="header-right"><a class="header-kitchen" href="{path('/kitchen/')}">OPEN THE KITCHEN <span aria-hidden="true">↗</span></a><button class="menu-trigger" type="button" aria-label="Open menu" aria-expanded="false" aria-controls="mobile-navigation"><span></span><span></span></button></div></header>
<nav class="mobile-nav" id="mobile-navigation" aria-label="Mobile navigation" hidden>{links}<a href="{path('/kitchen/')}">LET'S COOK ↗</a></nav>'''
def footer():
 return f'''<footer class="footer"><div class="footer-top wrap"><span class="kicker">AND A LITTLE MORE...</span><h2>COME HUNGRY.<br><em>LEAVE CURIOUS.</em></h2><div class="footer-bottom-cta"><span>Good food is made to be shared.<br>So are good stories.</span><a class="round-arrow" href="{path('/recipes/')}" aria-label="Explore recipes">↗</a></div></div>
<div class="footer-mid wrap"><a class="footer-wordmark" href="{path()}">MESA<span>●</span></a><div class="footer-links"><a href="{path('/recipes/')}">RECIPES</a><a href="{path('/kitchen/')}">THE KITCHEN</a><a href="{path('/stories/')}">STORIES</a><a href="{path('/about/')}">ABOUT</a></div></div>
<div class="footer-legal wrap"><span>© MESA — AN ORIGINAL FICTIONAL CULINARY JOURNAL</span><span>DESIGNED &amp; DEVELOPED BY <a href="https://www.pfxamd.com" target="_blank" rel="noopener noreferrer">pfxamd ↗</a></span><a href="#top">BACK TO TOP ↑</a></div></footer>'''
def layout(title,description,body,current='',og=1,kind='website',extra=''):
 meta=IMAGES[og];ogurl=ORIGIN+path(meta['src']);url=ORIGIN+path('/' if not current or current=='home' else '/'+current+'/')
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#fff7e8"><meta name="description" content="{e(description)}"><meta property="og:type" content="{kind}"><meta property="og:title" content="{e(title)} — MESA"><meta property="og:description" content="{e(description)}"><meta property="og:image" content="{e(ogurl)}"><meta name="color-scheme" content="light"><title>{e(title)} — MESA</title><link rel="icon" href="{path('/assets/mesa-mark.svg')}" type="image/svg+xml"><link rel="stylesheet" href="{path('/assets/site.css')}"><script src="{path('/assets/site.js')}" defer></script></head><body data-page="{e(current)}"><a href="#main" class="skip-link">Skip to content</a>{nav(current)}<main id="main">{body}</main>{footer()}{extra}</body></html>'''
def n(num):return f'{num:02d}'
def badge(text):return f'<span class="eyebrow">{e(text)}</span>'
def link(label,href,cls='text-link'):
 return f'<a href="{path(href)}" class="{cls}">{e(label)} <span aria-hidden="true">↗</span></a>'
def recipe_card(r,variant=''):
 number=r['number'];return f'''<article class="recipe-card {e(variant)}" data-category="{e(r['category'])}" data-recipe-card><a class="recipe-card-image" href="{path('/recipes/'+r['slug']+'/')}">{image(number+6,r['title']+', a finished MESA recipe')}
<span class="image-circle" aria-hidden="true">↗</span></a><div class="recipe-card-meta"><span>{n(number)} / {e(r['category'])}</span><span>{r['prep']+r['cook']} MIN</span></div><h3><a href="{path('/recipes/'+r['slug']+'/')}">{e(r['title'])}</a></h3><p>{e(r['deck'])}</p></article>'''
def story_card(st,kind=''):
 n=int(st['number']);return f'''<article class="story-card {e(kind)}"><a href="{path('/stories/'+st['slug']+'/')}" class="story-image">{image(n+30,st['title']+' editorial photograph')}<span class="image-circle" aria-hidden="true">↗</span></a><div class="story-details"><span class="eyebrow">THE STORIES / {st['number']} — {e(st['eyebrow'])}</span><h3><a href="{path('/stories/'+st['slug']+'/')}">{e(st['title'])}</a></h3><p>{e(st['deck'])}</p>{link('Read the story','/stories/'+st['slug']+'/')}</div></article>'''
def home():
 featured=RECIPES[4];cards=''.join(recipe_card(r, 'feature-card' if i==1 else '') for i,r in enumerate([RECIPES[0],RECIPES[1],RECIPES[3]]))
 story_items=''.join(story_card(st,'home-story' if i%2==0 else 'home-story offset') for i,st in enumerate(STORIES[:2]))
 body=f'''<section class="home-hero wrap"><div class="hero-prelude"><span>ISSUE N°001 — OCTOBER 2026</span><span>FOOD / COLOUR / CURIOSITY</span></div>
<div class="hero-main"><div class="hero-copy"><div class="hero-small">A JOURNAL OF THINGS WE LOVE TO EAT <span aria-hidden="true">✳</span></div><h1>GOOD<br><i>FOOD.</i><br>BIG<br>FEELINGS<span class="period">.</span></h1><div class="hero-copy-base"><p>For the everyday cooks, the curious eaters, and anyone who knows a good meal is about more than what's on the plate.</p>{link('EXPLORE THE ISSUE','/recipes/','pill-link')}</div></div>
<div class="hero-media">{image(1,'Shared lunch table with ripe tomatoes, torn bread, lemon and fresh herbs',eager=True,priority=True)}<div class="hero-media-stamp"><b>01</b><span>THE<br>EVERYDAY<br>TABLE</span></div><span class="hero-media-caption">FROM MARKET TO TABLE · VOLUME 01</span></div></div>
<div class="hero-bottom"><span>MADE TO BE READ, COOKED & SHARED.</span><span>SCROLL TO EXPLORE ↓</span></div></section>
<div class="ticker" aria-hidden="true"><div>GOOD FOOD, BETTER DAYS <b>✳</b> IN SEASON, IN COLOUR <b>✳</b> GOOD FOOD, BETTER DAYS <b>✳</b> IN SEASON, IN COLOUR <b>✳</b></div></div>
<section class="home-intro wrap section"><div class="index-heading">{badge('01 / A LITTLE INTRODUCTION')}<span>YOU ARE HERE ↘</span></div><div class="intro-layout"><h2>NO RULES.<br>JUST <em>GOOD TASTE.</em></h2><div class="intro-side"><p>A tomato at its ripest. Bread torn at the table. The kind of recipe you make twice in a week. MESA celebrates the small, very good things.</p>{link('MEET MESA','/about/')}</div>{image(2,'Close-up of three heirloom tomatoes showing juicy cut surfaces','intro-tomato')}</div></section>
<section class="featured section" aria-labelledby="featured-title"><div class="featured-left"><span class="kicker">02 / THE MAIN TABLE</span><div><span class="section-index">THIS WEEK'S RECIPE <span aria-hidden="true">↗</span></span><h2 id="featured-title">A LITTLE<br><i>MESS IS</i><br>MAGIC.</h2><p>Sweet roasted peppers. A pile of ribbons. The simplest sort of very good dinner.</p>{link('COOK THIS RECIPE','/recipes/'+featured['slug']+'/','pill-link light')}</div><span class="featured-serial">RECIPE R05 — 50 MIN — FOUR AT THE TABLE</span></div><div class="featured-photo">{image(11,'Roasted pepper and tomato ribbon pasta in a cobalt blue ceramic plate')}<span class="big-arrow" aria-hidden="true">↗</span></div></section>
<section class="section recipe-selection wrap"><div class="section-heading"><div>{badge('03 / GET COOKING')}<h2>WHAT'S <em>ON THE MENU?</em></h2></div><p>A little something for any kind of day. Made for real kitchens, not perfect ones.</p></div><div class="selection-grid">{cards}</div><div class="section-end"><span>TWELVE RECIPES / ONE TABLE</span>{link('ALL THE RECIPES','/recipes/')}</div></section>
<section class="citrus-feature section"><div class="citrus-photos">{image(3,'Overhead lemons and orange in graphic afternoon sunlight')}{image(33,'Botanical lemon branch on terracotta in afternoon light')}</div><div class="citrus-copy"><span class="kicker">04 / THE INGREDIENT NOTE</span><h2>WHEN LIFE<br>GIVES YOU<br><i>LEMONS...</i></h2><p>A squeeze here, a little zest there. The brightest things rarely need much explaining.</p>{link('READ THE STORY','/stories/an-ode-to-the-lemon/','pill-link dark')}</div></section>
<section class="kitchen-callout section wrap"><div class="index-heading">{badge('05 / SOMETHING TO PLAY WITH')}<span>YOU BRING THE INGREDIENTS ↘</span></div><div class="kitchen-callout-top"><h2>WHAT'S IN<br>YOUR <em>KITCHEN?</em></h2><p>Open the cupboard. Pick what you have. We'll help you find your next good idea — from the recipes in this issue.</p></div><div class="kitchen-callout-photo">{image(5,'Hands gathering fresh parsley from a metal bowl')}
<div class="kitchen-paper"><span>THE MESA KITCHEN</span><div class="paper-pills"><span>TOMATO</span><span>GARLIC</span><span>LEMON</span><span>+ YOUR INGREDIENTS</span></div><h3>YOUR PANTRY.<br><em>YOUR NEXT PLATE.</em></h3>{link('FIND SOMETHING TO COOK','/kitchen/','pill-link')}</div></div></section>
<section class="home-stories section wrap"><div class="section-heading"><div>{badge('06 / BEYOND THE RECIPE')}<h2>A STORY <em>BEHIND EVERY BITE.</em></h2></div><p>Other ways to look at a world that always finds its way back to the table.</p></div><div class="home-stories-grid">{story_items}</div><div class="section-end"><span>FOUR ORIGINAL STORIES</span>{link('EXPLORE ALL STORIES','/stories/')}</div></section>
<section class="closing-image">{image(6,'The calm after lunch, with a nearly empty dining table and warm evening sunlight')}<div class="closing-image-content"><span>FROM MARKET TO TABLE / 001</span><h2>HERE'S TO<br><i>THE GOOD STUFF.</i></h2></div></section>'''
 return layout('The Everyday Table','An original culinary journal of recipes, fresh ingredients and stories worth sharing.',body,'home',1)
def recipe_index():
 cards=''.join(recipe_card(r) for r in RECIPES)
 body=f'''<section class="collection-hero wrap"><div class="collection-intro">{badge('MESA / THE COOKBOOK / VOL 01')}<h1>THINGS<br>WORTH <i>MAKING.</i></h1><p>Twelve ways to find something good in an ordinary day. Simple ingredients, generous flavours and absolutely no need for a perfect kitchen.</p></div><div class="collection-hero-img">{image(2,'Close-up study of ripe heirloom tomatoes',eager=True,priority=True)}<span>FRESH IDEAS, NO FUSS.</span></div></section>
<section class="recipe-index section wrap"><div class="index-toolbar"><div><span class="kicker">THE COMPLETE RECIPE EDITION</span><p><strong>12</strong> RECIPES / FROM MARKET TO TABLE</p></div><div class="category-buttons" role="group" aria-label="Filter recipes"><button class="category-button is-active" type="button" data-filter="All" aria-pressed="true">ALL <small>12</small></button><button class="category-button" type="button" data-filter="Small Plates" aria-pressed="false">SMALL PLATES <small>04</small></button><button class="category-button" type="button" data-filter="The Main Table" aria-pressed="false">MAIN TABLE <small>05</small></button><button class="category-button" type="button" data-filter="Something Sweet" aria-pressed="false">SOMETHING SWEET <small>03</small></button></div></div>
<div class="all-recipe-grid" id="recipe-grid">{cards}</div><p class="empty-category" hidden>No recipes in this category.</p></section><section class="recipe-index-close"><div class="wrap"><span class="eyebrow">DON'T HAVE EVERYTHING?</span><h2>START WITH<br><em>WHAT YOU HAVE.</em></h2>{link('OPEN THE KITCHEN','/kitchen/','pill-link')}</div>{image(4,'Broken handmade bread on warm paper')}</section>'''
 return layout('Recipes','Explore twelve original editorial recipes, from bright small plates to hearty dinners and simple desserts.',body,'recipes',2)
def pretty_qty(q):
 if q is None:return ''
 return f'{q:g}' if isinstance(q,(float,int)) else str(q)
def recipe_detail(r):
 id=r['number'];duration=r['prep']+r['cook']+r.get('rest',0)
 ingredients=''.join(f'''<li><label class="ingredient-row"><input type="checkbox" data-ingredient-check><span class="fake-check" aria-hidden="true"></span><span class="amount" data-amount="{e(i['qty'] if i['qty'] is not None else '')}" data-unit="{e(i['unit'])}">{e(pretty_qty(i['qty']))} {e(i['unit'])}</span><span class="ingredient-name">{e(i['name'])}</span></label></li>''' for i in r['ingredients'])
 steps=''.join(f'<li><span class="step-number">{n(j)}</span><p>{e(step)}</p></li>' for j,step in enumerate(r['steps'],1))
 data=json.dumps({'title':r['title'],'steps':r['steps'],'serves':r['serves'],'slug':r['slug']}).replace('<','\\u003c')
 related=[x for x in RECIPES if x['slug']!=r['slug'] and x['category']==r['category']][:2]
 if len(related)<2:related.append(next(x for x in RECIPES if x['slug']!=r['slug'] and x not in related))
 rel=''.join(recipe_card(x) for x in related[:2])
 intro=f'''<section class="recipe-hero wrap"><div class="recipe-hero-copy"><a class="back-link" href="{path('/recipes/')}">← BACK TO ALL RECIPES</a><span class="eyebrow">RECIPE R{n(id)} / {e(r['category'])}</span><h1>{e(r['title'])}<span class="recipe-title-dot">.</span></h1><p class="recipe-deck">{e(r['deck'])}</p><div class="recipe-facts"><div><span>PREP</span><strong>{r['prep']}<small>MIN</small></strong></div><div><span>COOK</span><strong>{r['cook']}<small>MIN</small></strong></div><div><span>YIELD</span><strong>{r['serves']}<small>{'PCS' if id==12 else 'PORTIONS' if id==10 else 'PEOPLE'}</small></strong></div></div><a class="jump-cook" href="#recipe-method">LET'S MAKE IT ↘</a></div><div class="recipe-hero-media">{image(id+6,r['title']+', the finished dish',eager=True,priority=True)}<span class="recipe-image-label">THE FINISHED PLATE / R{n(id)}</span></div></section>'''
 contents=f'''<section class="recipe-content wrap section" id="recipe-method"><div class="recipe-side"><div class="side-intro"><span class="eyebrow">THE RECIPE / R{n(id)}</span><h2>LET'S GET<br><em>INTO IT.</em></h2><p>Everything you need, in the order you'll use it. Follow along at your own pace.</p></div><div class="cook-sticker"><span>✳</span> MADE TO<br>BE MADE</div></div><div class="recipe-primary"><section class="ingredients-panel" aria-labelledby="ingredients-title"><div class="panel-heading"><div><span class="eyebrow">01 / GET IT TOGETHER</span><h3 id="ingredients-title">Ingredients</h3></div><div class="serving-control"><span>MAKES</span><button type="button" data-servings-minus aria-label="Decrease portions">−</button><output data-servings>{r['serves']}</output><button type="button" data-servings-plus aria-label="Increase portions">+</button></div></div><ul class="ingredient-list">{ingredients}</ul><p class="ingredient-status" aria-live="polite"><span data-checked-count>0</span> / {len(r['ingredients'])} ingredients checked</p></section>
<section class="method-panel"><div class="panel-heading"><div><span class="eyebrow">02 / LET'S COOK</span><h3>The Method</h3></div><span class="step-summary">{len(r['steps'])} STEPS / APPROX {duration} MIN</span></div><ol class="method-list">{steps}</ol><button type="button" class="cook-launch" data-open-cook>START COOKING MODE <span aria-hidden="true">↗</span></button></section>
<div class="recipe-note"><span class="eyebrow">A NOTE FROM THE KITCHEN</span><p>{e(r['note'])}</p><p class="untested">Editorial recipe draft. Times and quantities have not been kitchen-tested.</p></div></div></section>
<section class="process-section"><div class="wrap process-grid"><div class="process-img">{image(id+18,'Preparation scene for '+r['title'])}</div><div class="process-copy"><span class="eyebrow">IN THE MAKING / R{n(id)}</span><h2>THE GOOD<br><em>PART IS</em><br>MAKING IT.</h2><p>Equipment: {e(r['equipment'])}.</p><a href="#recipe-method" class="text-link">BACK TO THE METHOD <span aria-hidden="true">↗</span></a></div></div></section><section class="recipe-next section wrap"><div class="section-heading"><div>{badge('KEEP COOKING')}<h2>MORE TO <em>MAKE.</em></h2></div>{link('ALL RECIPES','/recipes/')}</div><div class="related-grid">{rel}</div></section>'''
 modal=f'''<dialog class="cook-dialog" id="cook-dialog" aria-label="Cooking mode"><div class="cook-dialog-head"><span>THE MESA KITCHEN / COOKING MODE</span><button type="button" data-close-cook aria-label="Close cooking mode">✕</button></div><div class="cook-dialog-body"><div class="cook-mode-no"><span>STEP</span><strong data-step-index>01</strong><span>/ {n(len(r['steps']))}</span></div><h2>{e(r['title'])}</h2><p data-step-text>{e(r['steps'][0])}</p><div class="cook-timer"><span>NEED A TIMER?</span><div><button type="button" data-timer-start="300">5 MIN</button><button type="button" data-timer-start="600">10 MIN</button><button type="button" data-timer-start="900">15 MIN</button><button type="button" data-timer-reset>RESET</button></div><output aria-live="off" data-timer-display>00:00</output></div></div><div class="cook-dialog-foot"><button type="button" data-step-back>← PREVIOUS</button><div class="cook-progress"><span data-step-progress>01 / {n(len(r['steps']))}</span></div><button type="button" data-step-forward>NEXT STEP →</button></div></dialog><script type="application/json" id="recipe-data">{data}</script>'''
 return layout(r['title'],r['deck']+' Find ingredients, cooking steps and preparation photographs.',intro+contents,'recipes',id+6,'article',modal)
def kitchen():
 recipes_json=json.dumps([{'slug':r['slug'],'title':r['title'],'hero':path(r['hero']),'serves':r['serves'],'duration':r['prep']+r['cook'],'category':r['category'],'needs':[i['id'] for i in r['ingredients'] if i['id'] not in ('fine-salt','black-pepper','water')]} for r in RECIPES]).replace('<','\\u003c')
 names={'fresh-tomatoes':'Tomatoes','sourdough-bread':'Bread','olive-oil':'Olive Oil','garlic':'Garlic','fresh-basil':'Basil','canned-white-beans':'Butter Beans','lemon':'Lemon','flat-leaf-parsley':'Parsley','baby-potatoes':'Potatoes','plain-yogurt':'Yogurt','dijon-mustard':'Mustard','fresh-dill':'Dill','carrots':'Carrots','fennel':'Fennel','orange':'Oranges','pasta':'Pasta','red-bell-peppers':'Red Peppers','canned-chickpeas':'Chickpeas','canned-tomatoes':'Tinned Tomatoes','harissa-paste':'Harissa','spinach':'Spinach','onion':'Onion','aubergine':'Aubergine','sesame-seeds':'Sesame','whole-chicken':'Chicken','fresh-thyme':'Thyme','long-grain-rice':'Rice','saffron':'Saffron','vegetable-stock':'Vegetable Stock','plain-flour':'Flour','caster-sugar':'Caster Sugar','baking-powder':'Baking Powder','eggs':'Eggs','vanilla-extract':'Vanilla','pears':'Pears','honey':'Honey','butter':'Butter','walnuts':'Walnuts','cinnamon':'Cinnamon','cocoa-powder':'Cocoa','tahini':'Tahini','light-brown-sugar':'Brown Sugar'}
 count={k:sum(1 for r in RECIPES if k in [i['id'] for i in r['ingredients']]) for k in names}
 chips=''.join(f'<button type="button" class="pantry-chip" data-pantry-ingredient="{e(k)}" aria-pressed="false">{e(v)}<span aria-hidden="true">+</span></button>' for k,v in sorted(names.items(),key=lambda i:(-count[i[0]],i[1])))
 body=f'''<section class="kitchen-hero"><div class="wrap kitchen-hero-grid"><div class="kitchen-hero-copy"><span class="eyebrow">WELCOME TO THE MESA KITCHEN</span><h1>LESS<br>THINKING.<br><i>MORE</i><br>COOKING.</h1><p>Use what you've got. Find what you can make. Real recipes, no mystery ingredients hidden behind the door.</p><a href="#your-pantry" class="pill-link light">BUILD YOUR PANTRY <span aria-hidden="true">↘</span></a></div><div class="kitchen-hero-picture">{image(5,'Hands gathering fresh flat-leaf parsley from a steel colander',eager=True,priority=True)}<span>EVERYTHING STARTS SOMEWHERE.</span></div></div></section>
<section class="pantry-area wrap section" id="your-pantry"><div class="pantry-intro"><div><span class="eyebrow">01 / WHAT HAVE YOU GOT?</span><h2>OPEN THE<br><em>CUPBOARD.</em></h2></div><p>Tap each ingredient you have at home. We'll compare it against the 12 published recipes in this issue. Salt, pepper and water are assumed pantry basics.</p></div><div class="pantry-tools"><div class="pantry-tools-title"><strong>YOUR INGREDIENTS <span data-pantry-count>00</span></strong><button type="button" data-pantry-clear>CLEAR SELECTION ↺</button></div><div class="pantry-chips">{chips}</div></div>
<section class="kitchen-results" aria-labelledby="pantry-results-title"><div class="results-header"><div><span class="eyebrow">02 / WHAT CAN WE MAKE?</span><h2 id="pantry-results-title">YOUR NEXT <em>GOOD THING.</em></h2></div><span data-results-count>CHOOSE SOME INGREDIENTS</span></div><div class="kitchen-result-list" id="kitchen-matches"><p class="kitchen-fallback">Select a few ingredients above to see which published recipes fit. You can also browse <a href="{path('/recipes/')}">all twelve recipes</a> without using this tool.</p></div></section></section>
<section class="kitchen-closing"><div class="wrap kitchen-closing-grid"><div>{image(35,'Unlabelled pantry jars with beans, grains, pasta and olive oil')}</div><div><span class="eyebrow">A GOOD CUPBOARD IS A GOOD START</span><h2>A LITTLE<br><em>GOES A LONG WAY.</em></h2><p>A well-used pantry is better than a perfect one. All you need is a place to begin.</p>{link('READ THE GOOD PANTRY','/stories/the-good-pantry/')}</div></div></section><script type="application/json" id="kitchen-data">{recipes_json}</script>'''
 return layout('The Kitchen','Choose ingredients you have and discover which MESA recipes are closest to your pantry.',body,'kitchen',5)
def stories_index():
 top=STORIES[0];articles=''.join(story_card(st,'large-story' if i==0 else '') for i,st in enumerate(STORIES))
 body=f'''<section class="stories-hero"><div class="stories-hero-img">{image(31,'Morning produce market with tomatoes, herbs and aubergines',eager=True,priority=True)}</div><div class="stories-hero-overlay wrap"><span class="eyebrow">VOLUME 01 / MORE THAN A RECIPE</span><h1>NOT JUST<br><i>ON THE</i><br>PLATE.</h1><p>Good things have stories. Here's where we follow them.</p></div></section>
<section class="stories-list section wrap"><div class="index-heading">{badge('FOUR STORIES / THE EVERYDAY TABLE')}<span>READ A LITTLE DEEPER ↘</span></div><div class="story-index-grid">{articles}</div></section>'''
 return layout('Stories','Food stories about markets, lemons, pantry staples and moments around the table.',body,'stories',31)
def story_detail(st):
 i=int(st['number']);sections=''.join(f'<section><h2>{e(s[0])}</h2>'+''.join(f'<p>{e(p)}</p>' for p in s[1:])+'</section>' for s in st['sections'])
 others=[s for s in STORIES if s['slug']!=st['slug']][:2]
 more=''.join(story_card(s) for s in others)
 body=f'''<section class="article-hero wrap"><div class="article-eyebrow"><a href="{path('/stories/')}">← ALL STORIES</a><span>STORY / {st['number']} — {e(st['eyebrow'])}</span></div><h1>{e(st['title'])}<em>.</em></h1><p>{e(st['deck'])}</p><figure>{image(i+30,st['title']+', editorial photograph',eager=True,priority=True)}<figcaption>MESA / AN IMAGINED EDITORIAL WORLD / VOLUME 01</figcaption></figure></section>
<article class="article-body wrap"><aside><span class="eyebrow">FROM MARKET TO TABLE</span><span>THE EVERYDAY TABLE<br>VOLUME 01 / STORY {st['number']}</span>{link('BACK TO ALL STORIES','/stories/')}</aside><div class="article-text"><p class="article-lead">{e(st['intro'])}</p>{sections}<figure class="article-inline">{image({'01':32,'02':34,'03':4,'04':6}[st['number']],st['title']+', supporting editorial photograph')}<figcaption>A closer look / MESA editorial</figcaption></figure><p class="article-outro">There is always something more to notice at the table.</p></div></article><section class="article-more wrap section"><div class="section-heading"><div>{badge('AFTER THIS ONE')}<h2>KEEP <em>READING.</em></h2></div>{link('ALL STORIES','/stories/')}</div><div class="related-grid">{more}</div></section>'''
 return layout(st['title'],st['deck']+' An original MESA culinary editorial story.',body,'stories',i+30,'article')
def about():
 body=f'''<section class="about-hero wrap"><div class="about-top"><span class="eyebrow">MESA / THE EVERYDAY TABLE</span><span>AN INDEPENDENT CULINARY EXPERIMENT</span></div><h1>WE BELIEVE<br>IN THE <i>EVERYDAY</i><br>FEAST<span>.</span></h1><div class="about-bottom"><p>Not every meal is a celebration. We think it can still feel like one.</p><span>EST. IN IMAGINATION / VOL 01</span></div></section>
<section class="about-image">{image(1,'Editorial lunch table with tomatoes, bread and fresh ingredients')}</section><section class="about-manifesto section wrap"><div>{badge('THE IDEA')}<span class="about-asterisk" aria-hidden="true">✳</span></div><div><h2>FOOD IS NEVER<br><em>JUST FOOD.</em></h2><p>It's the first tomato you pick up at the market. The table you clear together. The half-forgotten ingredient that becomes dinner. MESA is a small journal devoted to those everyday details.</p><p>We wanted to make a place that doesn't feel like a recipe database. A place to look, read, choose and cook — where the photographs matter just as much as the practical steps.</p></div></section>
<section class="about-values"><div class="wrap"><span class="eyebrow">THREE THINGS ON OUR MIND</span><div class="about-value-grid"><article><span>01</span><h3>COLOUR IS A<br>GOOD THING.</h3><p>A bright tomato can do more than a dozen unnecessary decorations.</p></article><article><span>02</span><h3>MAKE IT<br>USEFUL.</h3><p>Real ingredient lists, sensible steps and a kitchen you can actually use.</p></article><article><span>03</span><h3>LEAVE ROOM<br>FOR PEOPLE.</h3><p>Good food is less about perfection and more about being together.</p></article></div></div></section>
<section class="about-facts section wrap"><div>{image(2,'Cut heirloom tomatoes as a tactile food material study')}</div><div><span class="eyebrow">A NOTE ON THIS EDITION</span><h2>A WORLD<br><em>MADE UP.</em><br>IN DETAIL.</h2><p>MESA is an original fictional publication and an independent web-design concept. The recipes are editorial drafts and have not been kitchen-tested. The photographs are conceptual generated imagery, not documentary evidence of real locations or people.</p><p>No products are sold, no user accounts are offered, and ingredients you select in The Kitchen stay in your browser.</p><p>Designed & developed by <a href="https://www.pfxamd.com" target="_blank" rel="noopener noreferrer">pfxamd ↗</a>.</p></div></section>'''
 return layout('About','Meet MESA, an original independent culinary publication and interactive website concept.',body,'about',1)
def error_page():
 return layout('Not Found','This page was not found at the MESA table.',f'<section class="notfound wrap"><span class="eyebrow">SOMETHING WENT MISSING</span><h1>404<i>.</i></h1><p>Looks like this one is off the menu.</p>{link('BACK TO THE TABLE','/','pill-link')}</section>','error',3)
def writepage(route,text):
 dest=DIST/route/'index.html' if route else DIST/'index.html'
 dest.parent.mkdir(exist_ok=True,parents=True);dest.write_text(text,encoding='utf-8')
def build():
 if DIST.exists():shutil.rmtree(DIST)
 (DIST/'assets').mkdir(parents=True,exist_ok=True)
 shutil.copytree(ROOT/'public/assets/images',DIST/'assets/images')
 shutil.copytree(ROOT/'assets',DIST/'assets',dirs_exist_ok=True)
 writepage('',home());writepage('recipes',recipe_index());writepage('kitchen',kitchen());writepage('stories',stories_index());writepage('about',about())
 for r in RECIPES:writepage('recipes/'+r['slug'],recipe_detail(r))
 for st in STORIES:writepage('stories/'+st['slug'],story_detail(st))
 (DIST/'404.html').write_text(error_page(),encoding='utf-8');(DIST/'.nojekyll').write_text('',encoding='utf-8')
 routes=['/','/recipes/','/kitchen/','/stories/','/about/']+['/recipes/'+r['slug']+'/' for r in RECIPES]+['/stories/'+st['slug']+'/' for st in STORIES]
 (DIST/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(f'<url><loc>{e(ORIGIN+path(p))}</loc></url>' for p in routes)+'</urlset>',encoding='utf-8')
 (DIST/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: '+ORIGIN+path('/sitemap.xml')+'\n',encoding='utf-8')
 print(f'MESA: built {len(routes)} static pages (+ 404) and {len(IMAGES)} images in {DIST}')
if __name__=='__main__':build()
